use crate::{Error,Result,journal,sandbox,util,view::View};use serde_json::{Value,json};use regex::{Regex,RegexBuilder};use sha2::{Digest,Sha256};use std::{path::Path,collections::BTreeMap};
const C:&str=r##"[{"name":"write","description":"Write the full contents of a file: create it, or replace the whole file. Every call writes the entire text, so a small change in the middle of a file should use edit rather than retyping it (retyping drops changes made elsewhere). The file is in the view as soon as this step lands: later reads and runs see it.","parameters":{"type":"object","properties":{"path":{"type":"string","description":"Relative path inside the view"},"content":{"type":"string","description":"The text to write"}},"required":["path","content"],"additionalProperties":false}},{"name":"edit","description":"Replace one exact string in a file: give old_string enough context to appear exactly once. When it is not unique the call reports that instead of guessing which one — then make old_string longer, or pass replace_all. To replace the whole file use write.","parameters":{"type":"object","properties":{"path":{"type":"string","description":"Relative path inside the view"},"old_string":{"type":"string","description":"The exact text to replace"},"new_string":{"type":"string","description":"The text to put in its place"},"replace_all":{"type":"boolean","description":"Replace every occurrence (default: one only)"}},"required":["path","old_string","new_string"],"additionalProperties":false}},{"name":"read_image","description":"Read an image and return the image itself. read only handles text files; images go through this one.","parameters":{"type":"object","properties":{"path":{"type":"string","description":"Relative path inside the view"}},"required":["path"],"additionalProperties":false}},{"name":"bash","description":"Run a shell command and get its exit code and output. **Only declared paths survive**: with a read-only work tree this command cannot change any file; with a writable one (round work) writes land in the tree but only the declared write paths are written back — anything outside them is reported and discarded. To produce files use write, or run an action (run_action). Suited to running tests, looking at repo state, or doing arithmetic.","parameters":{"type":"object","properties":{"command":{"type":"string","description":"The command line to run"},"cwd":{"type":"string","description":"Relative path to run in (default: the view root)"}},"required":["command"],"additionalProperties":false}},{"name":"read","description":"Read a file and return its text with line numbers. Read a slice when the file is long (offset is 1-based, limit caps the lines) — locate with grep first; that is cheaper than reading the whole file. To change it use edit or write; for images use read_image.","parameters":{"type":"object","properties":{"path":{"type":"string","description":"Relative path inside the view"},"offset":{"type":"integer","description":"First line to read (1-based)"},"limit":{"type":"integer","description":"Maximum number of lines"}},"required":["path"],"additionalProperties":false}},{"name":"glob","description":"Find files by path pattern and return the matching paths. Use it when you know part of a file name but not where it is; to search contents use grep. Searches from this step's working directory by default.","parameters":{"type":"object","properties":{"pattern":{"type":"string","description":"Path pattern, for example src/**/*.ts"},"path":{"type":"string","description":"Relative path to search under (default: the view root)"}},"required":["pattern"],"additionalProperties":false}},{"name":"grep","description":"Find files by content and return matching lines, file names, or counts (output_mode picks which; use content when unsure). To search paths rather than contents use glob.","parameters":{"type":"object","properties":{"pattern":{"type":"string","description":"Regular expression to match"},"path":{"type":"string","description":"Relative path to search under (default: the view root)"},"glob":{"type":"string","description":"Only look at these paths (path pattern)"},"output_mode":{"type":"string","enum":["content","files_with_matches","count"],"description":"Which kind of result to return"}},"required":["pattern"],"additionalProperties":false}},{"name":"todo_write","description":"Record the current to-do list: give it in full and it replaces the previous list. Write it before starting multi-step work and update the line as you advance (the one you are on uses in_progress). It is progress for yourself, not a report for anyone else.","parameters":{"type":"object","properties":{"todos":{"type":"array","description":"The complete list","items":{"type":"object","properties":{"content":{"type":"string","description":"What this item is"},"activeForm":{"type":"string","description":"How to phrase it while in progress"},"status":{"type":"string","enum":["pending","in_progress","completed"],"description":"Where it stands"}},"required":["content","status"],"additionalProperties":false}}},"required":["todos"],"additionalProperties":false}},{"name":"ask_user_question","description":"Ask a person a question, with options to choose from. **Use it only when the answer belongs to a person**: look up what is lookable (where the code is, how it works today), and settle what you can settle by the \"cleanest and most extensible\" rule. Several questions at a time are fine, each with options and a one-line note on what the choice costs.","parameters":{"type":"object","properties":{"questions":{"type":"array","description":"Questions to ask; several at a time are fine","items":{"type":"object","properties":{"question":{"type":"string","description":"What to ask"},"header":{"type":"string","description":"Short heading"},"multiSelect":{"type":"boolean","description":"May more than one be selected"},"options":{"type":"array","description":"The answers to pick from","items":{"type":"object","properties":{"label":{"type":"string","description":"The answer itself"},"description":{"type":"string","description":"One line on what this choice costs"}},"required":["label"],"additionalProperties":false}}},"required":["question"],"additionalProperties":false}}},"required":["questions"],"additionalProperties":false}},{"name":"exit_plan_mode","description":"Say that the planning phase is done: real work comes next, and a person opens the gate. Call it once the plan is complete, and make it the last call of that step — after handing it over you wait for approval before anything is touched.","parameters":{"type":"object","properties":{"plan":{"type":"string","description":"What you intend to do next"},"planFilePath":{"type":"string","description":"Which file this plan is written in"}},"required":["plan"],"additionalProperties":false}},{"name":"checkpoint","description":"Freeze the current view into one commit and get its id. Use it to leave a point you can come back to when a piece of work lands; a round also commits once by itself when it ends.","parameters":{"type":"object","properties":{"message":{"type":"string","description":"What this commit says"}},"required":["message"],"additionalProperties":false}},{"name":"run_action","description":"Run an action bound in this workspace (a build, a test). The bound actions are listed in the system state, each with its name and the command line it runs; pass extra arguments as args and they are appended to that command line. For a one-off command use bash.","parameters":{"type":"object","properties":{"action":{"type":"string","description":"The action name, bound in the config"},"args":{"type":"array","description":"Arguments passed to this action","items":{"type":"string"}}},"required":["action"],"additionalProperties":false}}]"##;
pub fn catalog()->Value{serde_json::from_str(C).expect("built-in catalog is validated by tests")}
fn e(s:impl Into<String>)->Error{Error::new(s)}fn text<'a>(v:&'a Value,k:&str)->Result<&'a str>{v.get(k).and_then(Value::as_str).ok_or_else(||e(format!("missing required string argument {k}")))}fn lines(t:&str)->usize{if t.is_empty(){0}else{t.split('\n').count()-usize::from(t.ends_with('\n'))}}fn cap(s:String)->String{if s.len()<=8192{return s}let mut a=4096;while !s.is_char_boundary(a){a-=1}let mut b=s.len()-4096;while !s.is_char_boundary(b){b-=1}format!("{}\n…({} bytes omitted · {} bytes and {} lines in all)…\n{}",&s[..a],b-a,s.len(),lines(&s),&s[b..])}fn ok(s:impl Into<String>)->Value{json!({"ok":true,"output":cap(s.into())})}fn no(s:impl Into<String>)->Value{json!({"ok":false,"output":cap(s.into())})}
fn valid(v:&Value,s:&Value,d:usize)->Result<()> {if d>16{return Err(e("tool arguments too deeply nested"))}if let Some(a)=s.get("enum").and_then(Value::as_array){if !a.contains(v){return Err(e("tool argument is outside its enum"))}}match s["type"].as_str(){Some("object")=>{let a=v.as_object().ok_or_else(||e("tool arguments must be objects"))?;let p=s["properties"].as_object().ok_or_else(||e("invalid built-in object schema"))?;if let Some(r)=s["required"].as_array(){for k in r{if !a.contains_key(k.as_str().ok_or_else(||e("invalid built-in required schema"))?){return Err(e(format!("missing required argument {}",k.as_str().unwrap_or(""))))}}}for(k,v)in a{let s=p.get(k).ok_or_else(||e(format!("unknown tool argument {k}")))?;valid(v,s,d+1)?;}},Some("array")=>{let a=v.as_array().ok_or_else(||e("tool argument must be an array"))?;if a.len()>1000{return Err(e("tool argument array exceeds budget"))}for v in a{valid(v,&s["items"],d+1)?;}},Some("string")=>{if !v.is_string()||v.as_str().is_some_and(|s|s.len()>util::MAX_BYTES){return Err(e("tool argument must be a bounded string"))}},Some("boolean")=>if !v.is_boolean(){return Err(e("tool argument must be boolean"))},Some("integer")=>if !v.is_u64()||v.as_u64().is_some_and(|n|n>9007199254740991){return Err(e("tool argument must be a nonnegative safe integer"))},_=>return Err(e("unsupported built-in schema"))}Ok(())}
fn norm(raw:&str,empty:bool)->Result<String>{if raw.len()>16384||raw.starts_with('/')||raw.contains(['\\','\0'])||raw.chars().any(char::is_control){return Err(e("absolute, malformed or control-character path refused"))}let mut a=Vec::new();for s in raw.split('/'){match s{""|"."=>{},".."=>if a.pop().is_none(){return Err(e("path escapes the view"))},_=>a.push(s)}}let p=a.join("/");if p.is_empty(){if empty{return Ok(p)}return Err(e("one concrete file path is required"))}util::rel(&p)?;Ok(p)}
fn fence(v:&View,p:&str)->Result<()> {let mut a=String::new();for s in p.split('/'){if !a.is_empty(){a.push('/')}a.push_str(s);if v.entries.get(&a).is_some_and(|e|e.kind=="symlink"){return Err(e(format!("path through symlink {a} refused")))}}Ok(())}
fn glob(s:&str)->Result<Regex>{if s.len()>4096||s.contains('\0'){return Err(e("glob pattern exceeds budget"))}let mut out="^".to_string();let a=s.chars().collect::<Vec<_>>();let mut i=0;while i<a.len(){match a[i]{'*' if a.get(i+1)==Some(&'*')=>{if a.get(i+2)==Some(&'/'){out.push_str("(?:.*/)?");i+=2}else{out.push_str(".*");i+=1}},'*'=>out.push_str("[^/]*"),'?'=>out.push_str("[^/]"),c=>out.push_str(&regex::escape(&c.to_string()))}i+=1;}out.push('$');RegexBuilder::new(&out).size_limit(1024*1024).dfa_size_limit(1024*1024).build().map_err(|_|e("glob compilation budget exceeded"))}
const RECEIPT_BYTES:usize=1024*1024;
fn receipt_add(total:&mut usize,n:usize)->Result<()> {*total=total.checked_add(n).filter(|n|*n<=RECEIPT_BYTES).ok_or_else(||e("search receipt byte budget exceeded; narrow the query"))?;Ok(())}
fn regex(s:&str)->Result<Regex>{if s.len()>4096{return Err(e("regular expression exceeds budget"))}RegexBuilder::new(s).size_limit(1024*1024).dfa_size_limit(1024*1024).build().map_err(|z|e(format!("unsupported or invalid regular expression: {z}")))}
fn deny(root:&Path,w:&str,p:&str,rule:&str)->Result<()> {journal::append(root,w,json!({"t":"bound/deny","agent":w,"path":p,"space":"virtual","rule":rule}))?;Ok(())}
fn scoped(p:&str,a:&[String])->bool{a.iter().any(|s|p==s||p.starts_with(&format!("{s}/")))}fn scope(c:&Value)->Result<Vec<String>>{let k=match c["kind"].as_str(){Some("resolve")=>"conflictPaths",Some("investigate")=>"evidenceRequired",_=>"ownedPaths"};let a=c.get(k).and_then(Value::as_array).ok_or_else(||e("contract does not declare a valid write scope"))?;if a.len()>1024{return Err(e("contract write scope item budget exceeded"))}let mut s=Vec::new();for p in a{let p=p.as_str().or_else(||p.get("artifact").and_then(Value::as_str)).ok_or_else(||e("invalid contract write scope"))?;util::rel(p)?;s.push(p.to_string());}Ok(s)}
pub fn invoke(root:&Path,w:&str,name:&str,args:&Value)->Result<Value>{util::ident(w)?;if let Err(z)=util::canonical(args){return Ok(no(z.message))}let entry=catalog().as_array().and_then(|a|a.iter().find(|x|x["name"]==name)).cloned();let Some(entry)=entry else{return Ok(no(format!("undeclared tool {name}")))};let mut args=args.as_object().cloned().ok_or_else(||e("tool arguments must be an object"))?;let mut ctx=BTreeMap::new();for k in ["__contract","__holder","__plan_path","__step","__writable"]{if let Some(v)=args.remove(k){ctx.insert(k,v);}}for k in ["__holder","__writable"]{if ctx.get(k).is_some_and(|v|!v.is_boolean()){return Ok(no(format!("{k} context must be boolean")))}}if ctx.get("__plan_path").is_some_and(|v|!v.is_string()){return Ok(no("plan-path context must be a string"))}let arg=Value::Object(args);if let Err(z)=valid(&arg,&entry["parameters"],0){return Ok(no(z.message))}let result=(||->Result<Value>{let mut v=View::load(root,w,None)?;let mut a=arg.clone();for k in match name{"read"|"write"|"edit"|"read_image"=>vec!["path"],"glob"|"grep"=>vec!["path"],"bash"=>vec!["cwd"],"exit_plan_mode"=>vec!["planFilePath"],_=>vec![]}{if let Some(p)=a.get(k).and_then(Value::as_str){let p=match norm(p,["cwd","path"].contains(&k)&&["glob","grep","bash"].contains(&name)){Ok(p)=>p,Err(z)=>{deny(root,w,p,"fence:path")?;return Ok(no(z.message))}};if let Err(z)=fence(&v,&p){deny(root,w,&p,"fence:through-symlink")?;return Ok(no(z.message))}a[k]=json!(p);}}if ["write","edit"].contains(&name){let p=text(&a,"path")?;if let Some(plan)=ctx.get("__plan_path"){let plan=plan.as_str().ok_or_else(||e("invalid plan-path context"))?;let dir=plan.rsplit_once('/').map(|x|x.0).unwrap_or("");if dir.is_empty()||!p.starts_with(&format!("{dir}/")){deny(root,w,p,"plan-scope")?;return Ok(no(format!("planning writes are restricted to {dir}")))}}if let Some(c)=ctx.get("__contract"){let s=scope(c)?;if !scoped(p,&s){deny(root,w,p,"contract-scope")?;return Ok(no(format!("write to {p} exceeds this contract's declared paths")))}}}
match name{"read"=>{let p=text(&a,"path")?;let Some(b)=v.read(p)?else{return Ok(no(format!("no {p} in the view (unreadable reads as absent — this layer does not tell the two apart).")))};let body=String::from_utf8(b.clone()).map_err(|_|e("read requires UTF-8 text; use read_image for binary data"))?;let mode=v.entries.get(p).map(|v|v.mode).unwrap_or(0o100644);let body2=if a.get("offset").is_some()||a.get("limit").is_some(){let offset=a.get("offset").and_then(Value::as_u64).unwrap_or(1);if offset==0{return Ok(no("read offset is 1-based"))}let limit=a.get("limit").and_then(Value::as_u64).unwrap_or(1000);if limit>100_000{return Ok(no("read limit exceeds line budget"))}body.lines().enumerate().skip((offset-1).min(usize::MAX as u64) as usize).take(limit as usize).map(|(i,s)|format!("{}\t{s}",i+1)).collect::<Vec<_>>().join("\n")}else{body.clone()};Ok(ok(format!("{p} ({} bytes · {} lines · mode {mode:o})\n{body2}",b.len(),lines(&body))))},"write"=>{let p=text(&a,"path")?;let b=text(&a,"content")?;let mode=v.entries.get(p).map(|e|e.mode);v.write(p,b.as_bytes(),mode)?;Ok(ok(format!("wrote {p} ({} bytes).",b.len())))},"edit"=>{let p=text(&a,"path")?;let old=text(&a,"old_string")?;let new=text(&a,"new_string")?;if old.is_empty(){return Ok(no("old_string must not be empty"))}let Some(b)=v.read(p)?else{return Ok(no(format!("no {p} in the view.")))};let b=String::from_utf8(b).map_err(|_|e("edit requires UTF-8 text"))?;let count=b.match_indices(old).count();if count==0{return Ok(no("old_string did not match; not one byte changed"))}let all=a.get("replace_all").and_then(Value::as_bool).unwrap_or(false);if count>1&&!all{return Ok(no(format!("old_string matches {count} occurrences; make it unique or use replace_all")))}let replacements=if all{count}else{1};let removed=replacements.checked_mul(old.len()).ok_or_else(||e("edited file exceeds byte budget"))?;let added=replacements.checked_mul(new.len()).ok_or_else(||e("edited file exceeds byte budget"))?;let length=b.len().checked_sub(removed).and_then(|n|n.checked_add(added)).filter(|n|*n<=util::MAX_BYTES).ok_or_else(||e("edited file exceeds byte budget"))?;let out=if all{b.replace(old,new)}else{b.replacen(old,new,1)};if out.len()!=length{return Err(e("replacement length changed unexpectedly"))}if out.len()>util::MAX_BYTES{return Ok(no("edited file exceeds byte budget"))}if out==b{return Ok(ok(format!("{p} unchanged (normalises to the current value); the view is still rev {}.",v.rev)))}let mode=v.entries.get(p).map(|e|e.mode);v.write(p,out.as_bytes(),mode)?;Ok(ok(format!("{p}: replaced {}.",if all{"every occurrence"}else{"one occurrence"})))},"read_image"=>{let p=text(&a,"path")?;match v.read(p)?{Some(b)=>Ok(ok(format!("{p}: an image of {} bytes (this version takes bytes only — it does not read pixels).",b.len()))),None=>Ok(no(format!("no {p} in the view.")))}},"glob"=>{let pat=text(&a,"pattern")?;let re=glob(pat)?;let dir=a["path"].as_str().unwrap_or("");let mut hit=Vec::new();let mut receipt=0usize;for p in v.entries.keys(){if (dir.is_empty()||p.starts_with(&format!("{dir}/")))&&re.is_match(p){receipt_add(&mut receipt,p.len()+1)?;if hit.len()>=100_000{return Err(e("glob match budget exceeded"))}hit.push(p.clone());}}if hit.is_empty(){Ok(ok(format!("no path matches {pat}.")))}else{Ok(ok(format!("{} paths:\n{}",hit.len(),hit.join("\n"))))}},"grep"=>{let pat=text(&a,"pattern")?;let re=regex(pat)?;let glob=a["glob"].as_str().map(glob).transpose()?;let dir=a["path"].as_str().unwrap_or("");let mode=a["output_mode"].as_str().unwrap_or("content");let mut hit=Vec::new();let mut count=0usize;let mut bytes=0usize;let mut receipt=0usize;for p in v.entries.keys(){if !dir.is_empty()&&p!=dir&&!p.starts_with(&format!("{dir}/")){continue}if glob.as_ref().is_some_and(|r|!r.is_match(p)){continue}if v.entries[p].kind!="file"{continue}let Some(b)=v.read(p)?else{continue};bytes=bytes.checked_add(b.len()).filter(|n|*n<=512*1024*1024).ok_or_else(||e("grep input byte budget exceeded"))?;let Ok(b)=std::str::from_utf8(&b)else{continue};let mut n=0;for(i,l)in b.split('\n').enumerate(){if re.is_match(l){n+=1;count+=1;if mode=="content"{receipt_add(&mut receipt,p.len().checked_add(l.len()).and_then(|n|n.checked_add(32)).ok_or_else(||e("search receipt byte budget exceeded"))?)?;hit.push(format!("{p}:{}:{l}",i+1));if hit.len()>100_000{return Err(e("grep match budget exceeded"))}}}}if n>0{if mode=="files_with_matches"{receipt_add(&mut receipt,p.len()+1)?;hit.push(p.clone())}else if mode=="count"{receipt_add(&mut receipt,p.len()+32)?;hit.push(format!("{p}:{n}"))}}}if hit.is_empty(){Ok(ok(format!("no line matches {pat}.")))}else{Ok(ok(format!("{} {}:\n{}",if mode=="content"{count}else{hit.len()},if mode=="content"{"lines"}else{"paths"},hit.join("\n"))))}},"todo_write"=>{let todos=a["todos"].as_array().ok_or_else(||e("todos must be an array"))?;let body=serde_json::to_string(&json!({"todos":todos}))?;journal::append(root,w,json!({"t":"holder/todos","agent":w,"digest":format!("{:x}",Sha256::digest(body.as_bytes()))[..16],"body":body}))?;let rows=todos.iter().map(|v|format!("- [{}] {}",match v["status"].as_str(){Some("completed")=>"x",Some("in_progress")=>"~",_=>" "},v["content"].as_str().unwrap_or(""))).collect::<Vec<_>>();Ok(ok(format!("todos recorded: {} (this whole list replaces the previous one):\n{}",todos.len(),rows.join("\n"))))},"ask_user_question"=>{let asks=a["questions"].as_array().ok_or_else(||e("questions must be an array"))?;if asks.is_empty()||asks.len()>3{return Ok(no("ask_user_question requires one to three questions"))}if !ctx.get("__holder").is_some_and(|v|v==true){return Ok(no("this cell holds a contract; carry human questions back to the holder cell"))}for q in asks{if q["question"].as_str().is_none_or(str::is_empty){return Ok(no("question text must not be empty"))}}let body=serde_json::to_string(&json!({"questions":asks}))?;journal::append(root,w,json!({"t":"holder/ask","agent":w,"digest":format!("{:x}",Sha256::digest(body.as_bytes()))[..16],"body":body}))?;Ok(json!({"ok":true,"halt":true,"output":format!("asked {} questions, and they are in the log. **This round stops at the door** — the human's answer goes in with `fugue say <one sentence>`; letting it through is still `fugue round go`.",asks.len())}))},"exit_plan_mode"=>{if !ctx.get("__holder").is_some_and(|v|v==true){return Ok(no("this cell holds a contract; the plan belongs to the holder"))}if let Some(p)=ctx.get("__plan_path").and_then(Value::as_str){if a.get("planFilePath").is_some_and(|v|v!=p){deny(root,w,a["planFilePath"].as_str().unwrap_or(""),"plan-path")?;return Ok(no(format!("planFilePath must be {p}")))}}let mut value=json!({"plan":a["plan"]});if let Some(p)=a.get("planFilePath"){value["path"]=p.clone()}let body=serde_json::to_string(&value)?;journal::append(root,w,json!({"t":"holder/plan","agent":w,"digest":format!("{:x}",Sha256::digest(body.as_bytes()))[..16],"body":body}))?;Ok(json!({"ok":true,"halt":true,"output":"the first state ends here: the plan is in the log. **This round stops at the door** — after a human reads it, `fugue round go` lets it through, and only then do the contracts go out."}))},"checkpoint"=>{if ctx.get("__holder").is_some_and(|v|v==true){return Ok(no("planning cannot advance branch refs; hand the plan over with exit_plan_mode and wait for approval"))}let msg=text(&a,"message")?;let r=v.checkpoint(msg)?;Ok(ok(format!("committed: {} — {msg}",r["commit"].as_str().unwrap_or(""))))},"bash"|"run_action"=>{let mut opts=json!({});if let Some(s)=ctx.get("__step"){opts["__step"]=s.clone()}if ctx.get("__holder").is_some_and(|v|v==true){opts["__write_scope"]=json!([]);}if let Some(c)=ctx.get("__contract"){let s=json!(scope(c)?);opts["__write_scope"]=s.clone();if !ctx.get("__holder").is_some_and(|v|v==true)&&ctx.get("__writable").is_some_and(|v|v==true){opts["mode"]=json!("workspace-write");opts["outputs"]=s.clone();}}let r=if name=="bash"{opts["cwd"]=json!(a["cwd"].as_str().unwrap_or(""));sandbox::execute(root,w,&["/bin/sh".into(),"-c".into(),text(&a,"command")?.into()],&opts)?}else{opts["extra"]=a.get("args").cloned().unwrap_or(json!([]));sandbox::run(root,w,text(&a,"action")?,&[],&opts)?};let head=if name=="bash"{format!("exit code {}{}",r["exit"],if r["denied"]==true{" · refused by the sandbox"}else{""})}else{format!("action {} exit code {}",text(&a,"action")?,r["exit"])};let stdout=r["stdout"].as_str().unwrap_or("");let stderr=r["stderr"].as_str().unwrap_or("");let body=if name=="bash"{[if stdout.is_empty(){String::new()}else{format!("stdout:\n{stdout}")},if stderr.is_empty(){String::new()}else{format!("stderr:\n{stderr}")}].into_iter().filter(|x|!x.is_empty()).collect::<Vec<_>>().join("\n")}else{[stdout,stderr].into_iter().filter(|s|!s.is_empty()).collect::<Vec<_>>().join("\n")};Ok(json!({"ok":r["exit"]==0,"output":cap(if body.is_empty(){head}else{format!("{head}\n{body}")})}))},_=>Err(e("unimplemented declared tool"))}})();match result{Ok(v)=>Ok(v),Err(z)=>Ok(no(z.message))}}
